/* Keep the element visible, fade it over 10s, then collapse instantly. */
.auto-fade-collapse {
  /* two animations:
     1) fadeOut animates opacity over 10s
     2) collapseAfter runs *instantly* after 10s to remove visible space */
  animation:
    fadeOut 10s linear forwards,
    collapseAfter 0.001s linear 10s forwards;

  /* initial constraints so collapse can work predictably */
  max-height: 200px; /* large enough for content */
  overflow: hidden;
}

/* Fade only — no size changes here */
@keyframes fadeOut {
  0%   { opacity: 1; }
  90%  { opacity: 1; } /* hold visible */
  100% { opacity: 0; }
}

/* Instant collapse that kicks in at 10s due to the delay on the animation */
@keyframes collapseAfter {
  0% {
    max-height: 200px;
    margin-bottom: 1rem; /* match your .mb-4 or adjust as needed */
    padding-top: inherit;
    padding-bottom: inherit;
    pointer-events: auto;
  }
  100% {
    max-height: 0;
    margin-bottom: 0;
    padding-top: 0;
    padding-bottom: 0;
    pointer-events: none;
  }
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  .auto-fade-collapse {
    animation: none;
  }
}

customScript.value:
const setFieldFocus = (id) => {
    const element = document.getElementById(id);
    if (element) {
        element.focus();
    }
};

const makePasswordToggle = (id) => {
    const container = document.getElementById(id);
    if (container) {
        const password = container.getElementsByTagName("input")[0];
        const toggler = document.createElement("button");
        toggler.setAttribute("type", "button");
        toggler.setAttribute("aria-label", "Show/Hide Password");
        toggler.className = "btn mdi mdi-eye-off-outline position-absolute end-0 top-50 translate-middle-y";
        container.appendChild(toggler);

        const showHidePassword = () => {
            if (password.type === "password") {
                password.type = "text";
                toggler.classList.add("mdi-eye-outline");
                toggler.classList.remove("mdi-eye-off-outline");
            } else {
                password.type = "password";
                toggler.classList.add("mdi-eye-off-outline");
                toggler.classList.remove("mdi-eye-outline");
            }
            password.focus();
        };

        toggler.addEventListener("click", showHidePassword);
    }
};

const start = () => {
    makePasswordToggle("passwordDiv");
    setFieldFocus("username");
};

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
} else {
    start();
}

