/**
 * Build KYXStart payload based on provided phone inputs.
 *
 * If a test phone value is provided, it takes precedence and enables test mode.
 * The testPhone value may contain both phone number and last name, separated by "|":
 *   "4089310002|Johnson"
 *
 * Otherwise, the primary phone number is used.
 *
 * @param {Object} input
 * @param {Object} input.params - Incoming parameters.
 * @param {string} [input.params.phone] - Primary phone number.
 * @param {string} [input.params.testPhone] - Optional test override in the format "phone|lastName".
 *
 * @returns {Promise<Object>} Object containing:
 *   {
 *     kyxstartPayload: Object
 *   }
 */
module.exports = async ({ params }) => {
  console.log('params: ', params);

  const { phone, testPhone } = params;

  const isTestMode = Boolean(testPhone);

  let resolvedPhone = phone;
  let resolvedLastName;

  if (isTestMode) {
    const [testPhoneNumber, testLastName] = testPhone
      .split('|')
      .map(value => value.trim());

    resolvedPhone = testPhoneNumber;
    resolvedLastName = testLastName;
  }

  const kyxstartPayload = {
    testMode: isTestMode,
    clientReference: 'test4',
    checks: isTestMode ? ['prefill'] : ['prefillExpress'],
    userConsent: true,
    country: 'USA',
    phoneNumber: resolvedPhone,
    ...(resolvedLastName ? { lastName: resolvedLastName } : {}),
    ...(isTestMode ? {} : { phoneLimit: 1 })
  };

  return {
    kyxstartPayload
  };
};

