/* ===============================
   Payee Account Status (Base)
   =============================== */

.payee-status {
  padding: 0.75rem 1rem;
  border-radius: 0.375rem;
  border-left: 4px solid transparent;
  background-color: #f8f9fa;
  font-size: 0.95rem;
}

/* Ensure icon aligns nicely with text */
.payee-status i {
  font-size: 1.1rem;
  line-height: 1.2;
}

/* ===============================
   Collapsible <details> Styling
   Applies to any payee-status block
   rendered as <details>
   =============================== */

.payee-status summary {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  list-style: none;
}

.payee-status summary::-webkit-details-marker {
  display: none;
}

.payee-status summary::after {
  content: '\f078'; /* fa-chevron-down */
  font-family: 'Font Awesome 6 Free';
  font-weight: 900;
  margin-left: auto;
  font-size: 0.75rem;
  opacity: 0.7;
}

.payee-status[open] summary::after {
  content: '\f077'; /* fa-chevron-up */
}

/* ===============================
   Verified
   =============================== */

.payee-status--verified {
  border-left-color: #198754;
  background-color: #f1f8f4;
}

.payee-status--verified i {
  color: #198754;
}

/* ===============================
   At Risk
   =============================== */

.payee-status--at-risk {
  border-left-color: #ffc107;
  background-color: #fff8e1;
}

.payee-status--at-risk i {
  color: #ffc107;
}

/* ===============================
   Unknown
   =============================== */

.payee-status--unknown {
  border-left-color: #dc3545;
  background-color: #f4f5f7;
}

.payee-status--unknown i {
  color: #dc3545;
}

/* ===============================
   Common Content Spacing
   =============================== */

.payee-status .fw-semibold {
  line-height: 1.3;
}

.payee-status .small {
  color: #495057;
}

/* Tighten spacing when placed near buttons */
.payee-status + .d-flex {
  margin-top: 0.25rem;
}

.kyxstart-verified {
  color: #198754 !important;
}

.kyxstart-unknown {
  color: #dc3545 !important;;
}

