/**
 * Applies data-* attributes from a selected element
 * to matching input fields by ID.
 *
 * Example:
 *   data-first-name="john" → #firstName.value = "john"
 */
function applyDataAttributesToFields(element) {
  if (!element) return;

  // Get selected option if this is a <select>
  const source = element.tagName === 'SELECT'
    ? element.options[element.selectedIndex]
    : element;

  if (!source) return;


  // Loop through dataset (auto maps data-* → camelCase)
  Object.entries(source.dataset).forEach(([key, value]) => {
    // Convert camelCase → exact ID match
    const field = document.getElementById(key);

    if (field) {
      field.value = value;
    }
  });
}

/**
 * Sets focus to the DOM element specified by its ID.
 * @param {string} id - The ID of the DOM element to focus.
 */
const setFieldFocus = (id) => {
    const element = document.getElementById(id);
    if (element) {
        element.focus();
    } else {
        console.log(`Element with ID ${id} not found.`);
    }
};

/**
 * Initializes the application by setting the focus to a specific field.
 */
const start = () => {
    // setFieldFocus("accountName");
    const testAccountSelector = document.getElementById('testAccountSelector');
    if (testAccountSelector) {
    testAccountSelector.addEventListener('change', function () {
        applyDataAttributesToFields(this);
    });
}

};

// Ensure the script runs after the DOM is fully loaded
if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
} else {
    start();
}

