const input = document.getElementById('cardnumber');
const icon = document.getElementById('cardBrandIcon');

/**
 * Applies data-* attributes from a selected element
 * to matching input fields by ID.
 *
 * Example:
 *   data-first-name="john" → #firstName.value = "john"
 */
function applyDataAttributesToFields(element) {
  if (!element) return;

  // Get selected option if this is a <select>
  const source = element.tagName === 'SELECT'
    ? element.options[element.selectedIndex]
    : element;

  if (!source) return;

  // Loop through dataset (auto maps data-* → camelCase)
  Object.entries(source.dataset).forEach(([key, value]) => {
    // Convert camelCase → exact ID match
    const field = document.getElementById(key);

    if (field) {
      field.value = value;
    }
  });

  // dispatch event to change card icon
  input.dispatchEvent(new Event('input', { bubbles: true }));
}

// Ensure the script runs after the DOM is fully loaded
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", start);
} else {

  start();
}

function start() {

  const testAccountSelector = document.getElementById('testAccountSelector');
  if (testAccountSelector) {
    testAccountSelector.addEventListener('change', function () {
      applyDataAttributesToFields(this);
    });
  }

  if (!input || !icon) return;

  function setIcon(classes) {
    icon.className =
      `position-absolute top-50 end-0 translate-middle-y me-3 ${classes}`;
  }

  function detectBrand(digits) {
    if (!digits) {
      return 'fa-regular fa-credit-card text-muted';
    }

    // Visa: starts with 4
    if (/^4/.test(digits)) {
      return 'fa-brands fa-cc-visa text-primary';
    }

    // Mastercard: 51–55, 2221–2720
    if (
      /^(5[1-5])/.test(digits) ||
      /^(222[1-9]|22[3-9]\d|2[3-6]\d{2}|27[01]\d|2720)/.test(digits)
    ) {
      return 'fa-brands fa-cc-mastercard text-danger';
    }

    // American Express: 34, 37
    if (/^(34|37)/.test(digits)) {
      return 'fa-brands fa-cc-amex text-info';
    }

    // Discover: 6011, 65, 644–649
    if (/^(6011|65|64[4-9])/.test(digits)) {
      return 'fa-brands fa-cc-discover text-warning';
    }

    // Default / unknown
    return 'fa-regular fa-credit-card text-muted';
  }

  // Initialize (supports browser autofill)
  const initialDigits = (input.value || '').replace(/\D/g, '');
  setIcon(detectBrand(initialDigits));

  input.addEventListener('input', () => {
    const digits = input.value.replace(/\D/g, '');
    setIcon(detectBrand(digits));
  });

}

