module.exports = async ({ params }) => {

  const { requiredVerificationLevel, userVerificationLevel } = params;

  // Define verification hierarchy
  const levels = {
    KYXSTART: 1,
    PINGONE: 2
  };

  const requiredLevel = levels[requiredVerificationLevel] || 0;
  const userLevel = levels[userVerificationLevel] || 0;

  const isUserVerified = userLevel >= requiredLevel;

  return {
    isUserVerified: isUserVerified
  };
};

