/**
 * Transform Verification Result → UI Summary + Reasons
 *
 * Purpose:
 * Converts a raw verification result object into UI-friendly content.
 * This includes:
 * - a summary status message based on the overall verification status
 * - a normalized array of reasons for detailed display in the UI
 *
 * Summary Status Rules:
 * - pass    → user may continue
 * - partial → user may continue, but should review details
 * - fail    → user is blocked from continuing
 *
 * Reason Type Mapping:
 * - RC* → "error"   (shown as red)
 * - MC* → "match"   (shown as green)
 * - other → "warning" (shown as yellow)
 *
 * Expected Input:
 * params = {
 *   status: "pass" | "partial" | "fail",
 *   result: {
 *     reasons: [
 *       { code: string, message: string }
 *     ]
 *   }
 * }
 *
 * Output:
 * {
 *   status: string,
 *   summaryText: string,
 *   canProceed: boolean,
 *   reasons: [
 *     { code: string, message: string, type: "error" | "warning" | "match" }
 *   ]
 * }
 */
module.exports = async ({ params }) => {
  // Safely extract inputs
  const status = (params.status || "").toLowerCase();
  const result = params.result || {};
  const reasons = Array.isArray(result.reasons) ? result.reasons : [];

  // Build top-level summary text from overall status
  let summaryText = "";
  let canProceed = false;

  if (status === "pass") {
    summaryText = "This account has been successfully verified. You can continue.";
    canProceed = true;
  } else if (status === "partialpass") {
    summaryText = "Some details couldn’t be fully verified. You can continue, but please review the information below.";
    canProceed = true;
  } else if (status === "fail") {
    summaryText = "This account couldn’t be verified. Please update the details or use a different account to continue.";
    canProceed = false;
  } else {
    summaryText = "We could not determine the verification status for this account. Please review the information below.";
    canProceed = false;
  }

  // Normalize and enrich each reason for UI consumption
  const uiReasons = reasons.map((reason) => {
    const code = reason.code || "";

    let type = "warning";
    if (code.startsWith("RC")) {
      type = "error";
    } else if (code.startsWith("MC")) {
      type = "match";
    }

    return {
      code,
      message: reason.message || "",
      type
    };
  });

  // Sort reasons by severity: error → warning → match
  const priority = {
    error: 0,
    warning: 1,
    match: 2
  };

  uiReasons.sort((a, b) => priority[a.type] - priority[b.type]);

  // Return summary + reasons for the UI
  return {
    status,
    summaryText,
    canProceed,
    reasons: uiReasons
  };
};

