/**
 * CRUD helper for accounts stored as an array of objects.
 *
 * Platform note:
 * - accountsList may arrive as an actual array/object OR as a JSON string.
 *
 * Inputs (params):
 * - action: "add" | "update" | "delete" | "get"
 * - accountsList: array/object/JSON-string representing the list of accounts
 * - id: required for update/delete/get
 * - account: required for add (full object shaped per your model); optional for update (patch object)
 *
 * Returns:
 * - accounts: normalized array of accounts
 * - account: selected account (for get, add, update) or null
 * - debug: diagnostic info (keep for now; remove later if desired)
 */

module.exports = async ({ params }) => {
  const { action, accountsList = [], id, account } = params;

  const normalizedAction =
    typeof action === "string" ? action.toLowerCase().trim() : "";

  const normalizedId =
    typeof id === "undefined" || id === null ? "" : String(id).trim();

  // -----------------------------
  // Normalize accountsList -> array
  // -----------------------------
  let accountsArray = [];
  let accountsSource = "unknown";
  let accountsParseError = null;

  if (Array.isArray(accountsList)) {
    accountsArray = [...accountsList];
    accountsSource = "array";
  } else if (typeof accountsList === "string" && accountsList.trim()) {
    try {
      const parsed = JSON.parse(accountsList);

      if (Array.isArray(parsed)) {
        accountsArray = [...parsed];
        accountsSource = "string.json.array";
      } else if (parsed && typeof parsed === "object" && Array.isArray(parsed.accounts)) {
        accountsArray = [...parsed.accounts];
        accountsSource = "string.json.object.accounts";
      } else if (parsed && typeof parsed === "object") {
        accountsArray = Object.values(parsed);
        accountsSource = "string.json.object.values";
      }
    } catch (e) {
      accountsArray = [];
      accountsSource = "string.json.parse_failed";
      accountsParseError = String(e && e.message ? e.message : e);
    }
  } else if (accountsList && typeof accountsList === "object") {
    if (Array.isArray(accountsList.accounts)) {
      accountsArray = [...accountsList.accounts];
      accountsSource = "object.accounts";
    } else {
      accountsArray = Object.values(accountsList);
      accountsSource = "object.values";
    }
  }

  // -----------------------------
  // Normalize account -> object
  // -----------------------------
  let accountObj = null;
  let accountSource = "none";
  let accountParseError = null;

  if (account && typeof account === "object" && !Array.isArray(account)) {
    accountObj = account;
    accountSource = "object";
  } else if (typeof account === "string" && account.trim()) {
    try {
      const parsed = JSON.parse(account);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        accountObj = parsed;
        accountSource = "string.json.object";
      } else {
        accountObj = null;
        accountSource = "string.json.not_object";
      }
    } catch (e) {
      accountObj = null;
      accountSource = "string.json.parse_failed";
      accountParseError = String(e && e.message ? e.message : e);
    }
  }

  const nowIso = () => new Date().toISOString();

  // Pure JS UUID v4 generator (no crypto dependency)
  const generateUUID = () =>
    "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
      const r = Math.random() * 16 | 0;
      const v = c === "x" ? r : (r & 0x3) | 0x8;
      return v.toString(16);
    });

  const normalizeAccountId = (value) =>
    typeof value === "undefined" || value === null ? "" : String(value).trim();

  const findIndexById = (arr, searchId) =>
    arr.findIndex((a) => a && typeof a === "object" && normalizeAccountId(a.id) === searchId);

  // -----------------------------
  // Derived field helpers
  // -----------------------------
  const MS_PER_DAY = 24 * 60 * 60 * 1000;

  const getDaysSinceLastVerification = (verificationDate) => {
    if (typeof verificationDate !== "string" || !verificationDate.trim()) {
      return null;
    }

    const parsed = new Date(verificationDate);
    const time = parsed.getTime();

    if (Number.isNaN(time)) {
      return null;
    }

    const diffMs = Date.now() - time;

    if (diffMs < 0) {
      return 0;
    }

    return Math.floor(diffMs / MS_PER_DAY);
  };

  const decorateAccount = (acct) => {
    if (!acct || typeof acct !== "object") {
      return acct;
    }

    return {
      ...acct,
      daysSinceLastVerification: getDaysSinceLastVerification(acct.kyxstartVerificationDate)
    };
  };

  let selectedAccount = null;
  let matchedIndex = -1;

  // ADD
  if (normalizedAction === "add" && accountObj && typeof accountObj === "object") {
    const newAccount = {
      ...accountObj,
      id: normalizeAccountId(accountObj.id) || generateUUID(),
      createdAt:
        (typeof accountObj.createdAt === "string" && accountObj.createdAt.trim())
          ? accountObj.createdAt.trim()
          : nowIso()
    };

    accountsArray.push(newAccount);
    selectedAccount = newAccount;
  }

  // UPDATE
  if (normalizedAction === "update" && normalizedId) {
    matchedIndex = findIndexById(accountsArray, normalizedId);

    if (matchedIndex !== -1) {
      const existing = accountsArray[matchedIndex];

      const safePatch =
        accountObj && typeof accountObj === "object" ? accountObj : {};

      const updated = {
        ...existing,
        ...safePatch,
        id: existing.id,
        createdAt: existing.createdAt,
        updatedAt: nowIso()
      };

      accountsArray[matchedIndex] = updated;
      selectedAccount = updated;
    }
  }

  // DELETE
  if (normalizedAction === "delete" && normalizedId) {
    matchedIndex = findIndexById(accountsArray, normalizedId);

    if (matchedIndex !== -1) {
      accountsArray.splice(matchedIndex, 1);
      selectedAccount = null;
    }
  }

  // GET
  if (normalizedAction === "get" && normalizedId) {
    matchedIndex = findIndexById(accountsArray, normalizedId);
    selectedAccount = matchedIndex === -1 ? null : accountsArray[matchedIndex];
  }

  // Add derived property to returned accounts
  const decoratedAccountsArray = accountsArray.map(decorateAccount);
  const decoratedSelectedAccount = decorateAccount(selectedAccount);

  // Serialize for storage-friendly persistence
  const accountsObject = { accounts: accountsArray };

  return {
    accounts: decoratedAccountsArray,
    accountsObject,
    account: decoratedSelectedAccount,
    debug: {
      rawAction: action,
      normalizedAction,
      incomingId: id,
      normalizedId,

      accountsListType: typeof accountsList,
      accountsSource,
      accountsParseError,

      accountType: typeof account,
      accountSource,
      accountParseError,
      accountKeys: accountObj && typeof accountObj === "object" ? Object.keys(accountObj) : [],

      accountCount: accountsArray.length,
      accountIds: accountsArray.map((a) => normalizeAccountId(a?.id) || null),

      matchedIndex,
      found: matchedIndex !== -1,
      updatedAccount:
        matchedIndex !== -1 && accountsArray[matchedIndex]
          ? accountsArray[matchedIndex]
          : null
    }
  };
};

