// Supported language: Javascript

/**
 * Build a BANK_ACCOUNT object for the KYXStart demo accounts model.
 *
 * Computes:
 * - id (GUID-like UUID v4) if not provided
 * - createdAt (ISO timestamp) if not provided
 * - bankLogoUrl from demo bank list if not provided (optional convenience)
 * - kyxstartVerificationDate only when updateVerificationDate is true
 *
 * Expects all required bank fields to be passed in.
 *
 * Notes:
 * - `reasons` may be passed as either:
 *   1. an array of objects
 *   2. a JSON string representing that array
 * - `updateVerificationDate` may be passed as a boolean or string ("true"/"false")
 * - `kyxstartVerificationDate` may be passed in and preserved when updateVerificationDate is false
 */
module.exports = async ({ params }) => {
