// Supported language: Javascript

/**
 * CRUD helper for transactions stored as an array of objects in PingOne.
 *
 * Storage model (custom attribute):
 *   { "transactions": [ { ...txn }, ... ] }
 *
 * Transaction model (top-level attributes only):
 * - id: GUID (generated if missing)
 * - displayId: short user-facing id (generated if missing)
 * - createdAt: ISO timestamp (defaults to now)
 * - createdAtDisplay: preformatted date string for UI (generated from createdAt)
 * - amount: string (always formatted with two decimals, e.g. "250.00")
 * - note: string (optional)
 * - from: full account snapshot object (copied from selected user account)
 * - to: full account snapshot object (copied from selected payee account)
 * - status: "Approved" | "In Review" | "Denied" (optional)
 *
 * Platform note:
 * - transactionsList may arrive as array/object OR JSON string.
 * - transaction/fromAccount/toAccount may arrive as object OR JSON string.
 *
 * Inputs (params):
 * - action: "create" | "add" | "update" | "delete" | "get"
 * - transactionsList: array/object/JSON-string representing the list of transactions
 * - id: required for update/delete/get
 *
 * For action="create":
 * - fromAccount: required (user account object or JSON string)
 * - toAccount: required (payee account object or JSON string)
 * - amount: required (number or numeric string)
 * - note: optional (string)
 * - status: optional ("Approved" | "In Review" | "Denied")
 * - createdAt: optional ISO timestamp
 * - displayId: optional user-facing id (if omitted, generated)
 *
 * For action="add":
 * - transaction: required (full transaction object; id/displayId/createdAt display will be normalized)
 *
 * For action="update":
 * - transaction: optional patch object (supports amount, createdAt, displayId, status, note)
 *
 * Returns:
 * - transactions: normalized array (sorted newest -> oldest by createdAt)
 * - transactionsObject: { transactions: [...] } for persistence (sorted newest -> oldest)
 * - transaction: selected transaction (for get, create/add, update) or null
 * - debug: diagnostic info
 */

module.exports = async ({ params }) => {
  const {
    action,
    transactionsList = [],
    id,

    // For add/update
    transaction,

    // For create
    fromAccount,
    toAccount,
    amount,
    note,
    status,
    createdAt,
    displayId
  } = params;

  const normalizedAction =
    typeof action === "string" ? action.toLowerCase().trim() : "";

  const normalizedId =
    typeof id === "undefined" || id === null ? "" : String(id).trim();

  const nowIso = () => new Date().toISOString();

  // Pure JS UUID v4 generator (no crypto dependency)
  const generateUUID = () =>
    "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
      const r = (Math.random() * 16) | 0;
      const v = c === "x" ? r : (r & 0x3) | 0x8;
      return v.toString(16);
    });

  // Short display id generator (demo-safe)
  const generateDisplayId = () => {
    const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // avoids 0/O/1/I
    let s = "";
    for (let i = 0; i < 6; i++) s += alphabet[(Math.random() * alphabet.length) | 0];
    return `TXN-${s}`;
  };

  const safeTrim = (v) => (typeof v === "string" ? v.trim() : v);

  const normalizeTxnId = (value) =>
    typeof value === "undefined" || value === null ? "" : String(value).trim();

  // Amount is treated as display-ready string (always 2 decimals)
  const normalizeAmount = (v) => {
    if (typeof v === "number" && Number.isFinite(v)) return v.toFixed(2);

    if (typeof v === "string" && v.trim()) {
      const n = Number(v.trim());
      return Number.isFinite(n) ? n.toFixed(2) : null;
    }

    return null;
  };

  const normalizeStatus = (v) => {
    if (typeof v !== "string" || !v.trim()) return null;
    const s = v.trim();
    if (s === "Approved" || s === "In Review" || s === "Denied") return s;
    return null;
  };

  const normalizeNote = (v) => {
    if (typeof v !== "string") return null;
    const s = v.trim();
    return s ? s : null;
  };

  const deepCopy = (obj) => {
    try {
      return JSON.parse(JSON.stringify(obj));
    } catch {
      return obj ? { ...obj } : obj;
    }
  };

  // Preformat display date for template rendering (no handlebars helpers needed)
  const formatDisplayDate = (iso) => {
    try {
      const d = new Date(iso);
      // "Mar 9, 2026" (stable, readable)
      return d.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric"
      });
    } catch {
      return iso;
    }
  };

  const parseJsonObjectMaybe = (value, label) => {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      return { obj: value, source: `${label}.object`, error: null };
    }
    if (typeof value === "string" && value.trim()) {
      try {
        const parsed = JSON.parse(value);
        if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
          return { obj: parsed, source: `${label}.string.json.object`, error: null };
        }
        return { obj: null, source: `${label}.string.json.not_object`, error: null };
      } catch (e) {
        return {
          obj: null,
          source: `${label}.string.json.parse_failed`,
          error: String(e && e.message ? e.message : e)
        };
      }
    }
    return { obj: null, source: `${label}.none`, error: null };
  };

  // -----------------------------
  // Normalize transactionsList -> array
  // -----------------------------
  let transactionsArray = [];
  let listSource = "unknown";
  let listParseError = null;

  if (Array.isArray(transactionsList)) {
    transactionsArray = [...transactionsList];
    listSource = "array";
  } else if (typeof transactionsList === "string" && transactionsList.trim()) {
    try {
      const parsed = JSON.parse(transactionsList);

      if (Array.isArray(parsed)) {
        transactionsArray = [...parsed];
        listSource = "string.json.array";
      } else if (parsed && typeof parsed === "object" && Array.isArray(parsed.transactions)) {
        transactionsArray = [...parsed.transactions];
        listSource = "string.json.object.transactions";
      } else if (parsed && typeof parsed === "object") {
        transactionsArray = Object.values(parsed);
        listSource = "string.json.object.values";
      }
    } catch (e) {
      transactionsArray = [];
      listSource = "string.json.parse_failed";
      listParseError = String(e && e.message ? e.message : e);
    }
  } else if (transactionsList && typeof transactionsList === "object") {
    if (Array.isArray(transactionsList.transactions)) {
      transactionsArray = [...transactionsList.transactions];
      listSource = "object.transactions";
    } else {
      transactionsArray = Object.values(transactionsList);
      listSource = "object.values";
    }
  }

  const findIndexById = (arr, searchId) =>
    arr.findIndex((t) => t && typeof t === "object" && normalizeTxnId(t.id) === searchId);

  // -----------------------------
  // Normalize inputs that can be JSON strings
  // -----------------------------
  const parsedTxn = parseJsonObjectMaybe(transaction, "transaction");
  const txnObj = parsedTxn.obj;

  const parsedFrom = parseJsonObjectMaybe(fromAccount, "fromAccount");
  const fromObj = parsedFrom.obj;

  const parsedTo = parseJsonObjectMaybe(toAccount, "toAccount");
  const toObj = parsedTo.obj;

  let selectedTransaction = null;
  let matchedIndex = -1;

  // -----------------------------
  // CREATE (build from fromAccount/toAccount + amount + optional status/note)
  // -----------------------------
  if (normalizedAction === "create") {
    const amt = normalizeAmount(amount);
    const iso =
