// Supported language: Javascript

/**
 * Build a CREDIT_CARD object for the KYXStart demo accounts model.
 *
 * Accepts legacy/lowercase input fields for compatibility, but normalizes
 * overlapping output fields to the shared account model where practical.
 *
 * Computes:
 * - id (GUID-like UUID v4) if not provided
 * - createdAt (ISO timestamp) if not provided
 * - brand from cardnumber prefix if not provided
 * - cardLogoUrl from brand if not provided
 * - cardnumberMasked from cardnumber
 * - kyxstartVerificationDate only when updateVerificationDate is true
 *
 * Stores:
 * - cardnumber (full value, demo-only)
 */
module.exports = async ({ params }) => {
  const {
    id,
    createdAt,

    // Verification controls
    kyxstartVerificationDate,
    updateVerificationDate = false,

    // Accept current input names
    displayname,
    firstname,
    lastname,
    cardnumber,
    address1,
    city,
    state,
    postalcode,
    kyxstartStatus = "pass",
    reasons,

    // Optional overrides
    brand,
    cardLogoUrl
  } = params;

  const nowIso = () => new Date().toISOString();

  // Pure JS UUID v4 generator (no crypto dependency)
  const generateUUID = () =>
    "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
      const r = (Math.random() * 16) | 0;
      const v = c === "x" ? r : (r & 0x3) | 0x8;
      return v.toString(16);
    });

  const normalizeString = (v) => (typeof v === "string" ? v.trim() : v);
  const digitsOnly = (v) => String(v || "").replace(/\D/g, "");

  const normalizeBoolean = (value) => {
    if (typeof value === "boolean") {
      return value;
    }

    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();
      if (normalized === "true") return true;
      if (normalized === "false") return false;
    }

    return false;
  };

  const detectBrand = (digits) => {
    if (!digits) return "UNKNOWN";
    if (/^4/.test(digits)) return "VISA";
    if (
      /^(5[1-5])/.test(digits) ||
      /^(222[1-9]|22[3-9]\d|2[3-6]\d{2}|27[01]\d|2720)/.test(digits)
    ) {
      return "MASTERCARD";
    }
    if (/^(34|37)/.test(digits)) return "AMEX";
    if (/^(6011|65|64[4-9])/.test(digits)) return "DISCOVER";
    return "UNKNOWN";
  };

  const resolveCardLogoUrl = (detectedBrand) => {
    const baseUrl = "https://gmorgan-ping.github.io/kyxstart-poc/logos/";
    const map = {
      VISA: baseUrl + "visa.png",
      MASTERCARD: baseUrl + "mastercard.png",
      AMEX: baseUrl + "amex.png",
      DISCOVER: baseUrl + "discover.png"
    };
    return map[detectedBrand] || baseUrl + "default.png";
  };

  const maskLast4 = (digits) => {
    if (!digits) return "";
    return `•••• ${digits.slice(-4)}`;
  };

  // Safely normalize reasons into an array
  const normalizeReasons = (value) => {
    if (Array.isArray(value)) {
      return value;
    }

    if (typeof value === "string" && value.trim()) {
      try {
        const parsed = JSON.parse(value);
        return Array.isArray(parsed) ? parsed : [];
      } catch (err) {
        console.log("Unable to parse reasons JSON:", err);
        return [];
      }
    }

    return [];
  };

  const cardDigits = digitsOnly(cardnumber);
  const computedBrand = normalizeString(brand) || detectBrand(cardDigits);
  const computedLogoUrl =
    normalizeString(cardLogoUrl) || resolveCardLogoUrl(computedBrand);
  const computedVerificationDate = normalizeBoolean(updateVerificationDate)
    ? nowIso()
    : normalizeString(kyxstartVerificationDate) || null;

  const creditCard = {
  id: normalizeString(id) || generateUUID(),
  type: "CREDIT_CARD",
  createdAt: normalizeString(createdAt) || nowIso(),
  kyxstartVerificationDate: computedVerificationDate,

  accountName: normalizeString(displayname),
  firstName: normalizeString(firstname),
  lastName: normalizeString(lastname),

  cardnumber: cardDigits,
  cardnumberMasked: maskLast4(cardDigits),
  address1: normalizeString(address1),
  city: normalizeString(city),
  state: normalizeString(state),
  postalcode: normalizeString(postalcode),

  kyxstartStatus: normalizeString(kyxstartStatus) || "pass",
  reasons: normalizeReasons(reasons),
  brand: computedBrand,
  cardLogoUrl: computedLogoUrl
};

  return { account: creditCard };
};

